 2	/**
 3	 * @package Countries
 4	 * @subpackage API
 5	 */
 6	
 7	declare(strict_types=1);
 8	
 9	namespace Application\Countries\API\Params;
10	
11	use Application\API\Parameters\Type\IDListParameter;
12	use Application\AppFactory;
13	use Application_Countries_Country;
14	
15	/**
16	 * Country IDs parameter for the multi-country Countries API.
17	 *
18	 * Accepts one or more application country IDs as a comma-separated
19	 * string or array. Each ID is validated individually via
20	 * {@see AppCountryIDsValidation}, which produces a per-ID error message
21	 * identifying any IDs that do not exist.
22	 *
23	 * @package Countries
24	 * @subpackage API
25	 * @see AppCountryIDsHandler
26	 * @see AppCountriesParamInterface
27	 */
28	class AppCountryIDsParam extends IDListParameter implements AppCountriesParamInterface
29	{
30	    /**
31	     * The parameter name used in API requests.
32	     *
33	     * Mirrors the constant declared on {@see \Application\Countries\API\AppCountriesAPIInterface}.
34	     */
35	    public const string PARAM_COUNTRY_IDS = 'countryIDs';
36	
37	    public function __construct()
38	    {
39	        parent::__construct(self::PARAM_COUNTRY_IDS, 'Country IDs');
40	
41	        $this
42	            ->setDescription('One or more application country IDs, as a comma-separated list or array.')
43	            ->validateBy(new AppCountryIDsValidation());
44	    }
45	
46	    /**
47	     * Returns the resolved country objects for each ID in the parameter value.
48	     *
49	     * Returns an empty array if the parameter has no value.
50	     *
51	     * @return Application_Countries_Country[]
52	     */
53	    public function getCountries(): array
54	    {
55	        $ids = $this->getValue();
56	
57	        if($ids === null || empty($ids)) {
58	            return array();
59	        }
60	
61	        $result = array();
62	        $countries = AppFactory::createCountries();
63	
64	        foreach($ids as $id) {
65	            $result[] = $countries->getCountryByID($id);
66	        }
67	
68	        return $result;
69	    }
70	}

