11	use Application\API\Parameters\Handlers\BaseParamHandler;
12	use Application_Countries_Country;
13	use AppUtils\ClassHelper;
14	
15	/**
16	 * Handler that bridges {@see AppCountryIDsParam} into a
17	 * {@see \Application\API\Parameters\Handlers\BaseParamsHandlerContainer}.
18	 *
19	 * Provides type-narrowed overrides for {@see register()} and {@see getParam()}
20	 * so consumers receive a typed `AppCountryIDsParam` without casting.
21	 *
22	 * @package Countries
23	 * @subpackage API
24	 * @see AppCountryIDsParam
25	 */
26	class AppCountryIDsHandler extends BaseParamHandler
27	{
28	    /**
29	     * Resolves the list of countries from the registered parameter.
30	     *
31	     * @return Application_Countries_Country[]
32	     */
33	    protected function resolveValueFromSubject(): array
34	    {
35	        return $this->getParam()?->getCountries() ?? array();
36	    }
37	
38	    /**
39	     * Registers the parameter and returns it type-narrowed.
40	     *
41	     * @return AppCountryIDsParam
42	     */
43	    public function register(): AppCountryIDsParam
44	    {
45	        return ClassHelper::requireObjectInstanceOf(
46	            AppCountryIDsParam::class,
47	            parent::register()
48	        );
49	    }
50	
51	    /**
52	     * Returns the registered parameter type-narrowed, or `null` if not yet registered.
53	     *
54	     * @return AppCountryIDsParam|null
55	     */
56	    public function getParam(): ?AppCountryIDsParam
57	    {
58	        $param = parent::getParam();
59	
60	        if($param instanceof AppCountryIDsParam) {
61	            return $param;
62	        }
63	
64	        return null;
65	    }
66	
67	    protected function createParam(): AppCountryIDsParam
68	    {
69	        return new AppCountryIDsParam();
70	    }
71	}

