20	 * Country ID parameter for the Countries API.
21	 *
22	 * > NOTE: This implements {@see AppCountryParamInterface}
23	 * > to provide access to the resolved country object.
24	 *
25	 * @package Countries
26	 * @subpackage API
27	 */
28	class AppCountryIDParam extends IntegerParameter implements SelectableValueParamInterface, AppCountryParamInterface
29	{
30	    use SelectableValueParamTrait;
31	
32	    public function __construct()
33	    {
34	        parent::__construct(AppCountryAPIInterface::PARAM_COUNTRY_ID, 'App Country ID');
35	
36	        $this
37	            ->setDescription('Application country ID.')
38	            ->validateByValueExistsCallback(static function (mixed $value) : bool {
39	                if(is_numeric($value)) {
40	                    return AppFactory::createCountries()->idExists((int)$value);
41	                }
42	                return false;
43	            });
44	    }
45	
46	    public function getCountry() : ?Application_Countries_Country
47	    {
48	        $value = $this->getValue();
49	        if ($value === null) {
50	            return null;
51	        }
52	
53	        return AppFactory::createCountries()->getCountryByID($value);
54	    }
55	
56	    protected function _getValues(): array
57	    {
58	        $result = array();
59	        foreach (AppFactory::createCountries()->getAll() as $country) {
